/*
 * A266326  Triangle read by rows giving successive states of cellular
 *          automaton generated by "Rule 20" initiated with a single ON
 *          (black) cell.
 * https://oeis.org/A266326
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf, easy
 * Formula:   a(n) = 1 if let r = ⌊√n⌋, k = n − r², then (r even and k = 2r)
 *            or (r odd and k = 2r−1 or k = 2r); otherwise a(n) = 0
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <math.h>

/* Integer square root: greatest r with r*r <= n. */
static inline idx_t isqrt(idx_t n)
{
    if (n == 0) return 0;
    idx_t r = (idx_t)sqrt((long double)n);
    while ((r + 1) <= n / (r + 1)) ++r;
    while (r > n / r) --r;
    return r;
}

seq_t a(idx_t n)
{
    idx_t r = isqrt(n);                /* row number */
    idx_t offset = n - r * r;          /* position in the row */
    idx_t m = r * 2;                   /* last index of the row */

    if ((r & 1) == 0) {                /* even row → single trailing 1 */
        return offset == m ? (seq_t)1 : (seq_t)0;
    } else {                           /* odd row → two trailing 1s */
        return (offset == m - 1 || offset == m) ? (seq_t)1 : (seq_t)0;
    }
}
